{"path": "solution.py", "content": "def add_days(date_str, n):
    """add_days('2026-01-31', 3) == '2026-02-03'."""
    year, month, day = map(int, date_str.split('-'))
    # Convert date to day of the year
    day_of_year = 0
    for m in range(1, month):
        if m == 2:
            day_of_year += 28 + (1 if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0) else 0)
        elif m in [4, 6, 9, 11]:
            day_of_year += 30
        else:
            day_of_year += 31
    day_of_year += day
    # Add n days
    day_of_year += n
    # Handle negative days
    if day_of_year < 0:
        day_of_year += 365
    elif day_of_year > 365:
        day_of_year -= 365
    # Convert back to date
    year += day_of_year // 365
    day_of_year %= 365
    # Handle leap years for February
    if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
        feb_days = 29
    else:
        feb_days = 28
    # Find the month and day
    for month in range(1, 13):
        if month == 2:
            max_days = feb_days
        elif month in [4, 6, 9, 11]:
            max_days = 30
        else:
            max_days = 31
        if day_of_year >= max_days:
            day_of_year -= max_days
        else:
            break
    return f"{year}-{month:02d}-{day_of_year:02d}""}

