def add_days(date_str, n):
    """
    Given a date string 'YYYY-MM-DD' and an integer n (may be negative),
    return the date n days later as 'YYYY-MM-DD'.
    No imports allowed — implement calendar arithmetic.
    """
    # Parse the input date
    year, month, day = map(int, date_str.split('-'))

    # Handle positive n (adding days)
    if n >= 0:
        while n > 0:
            days_remaining_in_month = days_in_month(year, month) - day
            if n <= days_remaining_in_month:
                day += n
                n = 0
            else:
                n -= (days_remaining_in_month + 1)
                day = 1
                month += 1
                if month > 12:
                    month = 1
                    year += 1
    else:
        # Handle negative n (subtracting days)
        n = -n  # Work with positive number of days to subtract
        while n > 0:
            if day > n:
                day -= n
                n = 0
            else:
                n -= day
                month -= 1
                if month < 1:
                    month = 12
                    year -= 1
                day = days_in_month(year, month)

    # Format the result as 'YYYY-MM-DD'
    return f"{year:04d}-{month:02d}-{day:02d}"

